.task-row { display: flex; gap: 0.75rem; }
.task-title { flex: 1; min-width: 0; overflow-wrap: anywhere; }
@media (max-width: 38rem) {
  .task-row { flex-direction: column; }
}

function toggleTask(id) {
  tasks = tasks.map(task => task.id === id
    ? { ...task, done: !task.done }
    : task);
  render(); // 重新读取状态并更新列表
}
